"""Generate Rust, TypeScript, and VM guest constants from Python owners."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

from codex_layout import REPOSITORY_ROOT
from codex_shared_values import (
    MAX_PROJECT_SECRET_VALUE_BYTES,
    MAX_USER_ATTACHMENT_BYTES,
    project_secret_value_limit_label,
    user_attachment_limit_label,
)


OUTPUTS = {
    REPOSITORY_ROOT / "workspaces/runtime/packages/runtime-schema/src/shared_values.rs": (
        "// Generated by studio_api.generate_shared_values; do not edit.\n"
        "pub const MAX_USER_ATTACHMENT_BYTES: usize = "
        f"{MAX_USER_ATTACHMENT_BYTES};\n"
        "pub const USER_ATTACHMENT_LIMIT_LABEL: &str = "
        f'"{user_attachment_limit_label()}";\n'
    ),
    REPOSITORY_ROOT / "workspaces/client/apps/web/src/generated/sharedValues.ts": (
        "// Generated by studio_api.generate_shared_values; do not edit.\n"
        f"export const MAX_USER_ATTACHMENT_BYTES = {MAX_USER_ATTACHMENT_BYTES};\n"
        f'export const USER_ATTACHMENT_LIMIT_LABEL = "{user_attachment_limit_label()}";\n'
        f"export const MAX_PROJECT_SECRET_VALUE_BYTES = {MAX_PROJECT_SECRET_VALUE_BYTES};\n"
        f'export const PROJECT_SECRET_VALUE_LIMIT_LABEL = "{project_secret_value_limit_label()}";\n'
    ),
    REPOSITORY_ROOT / "workspaces/runtime/apps/vm-guest/shared_values_generated.py": (
        "# Generated by studio_api.generate_shared_values; do not edit.\n"
        f"MAX_PROJECT_SECRET_VALUE_BYTES = {MAX_PROJECT_SECRET_VALUE_BYTES}\n"
        f'PROJECT_SECRET_VALUE_LIMIT_LABEL = "{project_secret_value_limit_label()}"\n'
    ),
}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true", help="write generated shared values")
    mode.add_argument("--check", action="store_true", help="fail when generated values are stale")
    args = parser.parse_args(argv)
    for path, expected in OUTPUTS.items():
        try:
            current = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            current = None
        if args.check:
            if current != expected:
                print(f"{path.relative_to(REPOSITORY_ROOT)} is stale; run `pnpm run shared-values:generate`", file=sys.stderr)
                return 1
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
